package command

import (
	"maps"
	"sort"
	"strings"
)

// ViewType represents the view type
type ViewType string

const (
	ViewDashboard ViewType = "dashboard"
	ViewStatus    ViewType = "status"
	// ViewGitAuth and ViewGitExplorer are named after the *role*, not after a
	// platform: a context targets one forge (§3.6), so there is one
	// authentication screen and one explorer, and both adapt to whichever it
	// is. A `gitlab-` prefix would have to be typed as `github-` half the time
	// for the same view.
	ViewGitAuth       ViewType = "git-auth"
	ViewGitExplorer   ViewType = "git-explorer"
	ViewWorkspaces    ViewType = "workspaces"
	ViewSecurity      ViewType = "security"
	ViewContainers    ViewType = "containers"
	ViewOCIResources  ViewType = "oci-resources"
	ViewNetdiag       ViewType = "netdiag"
	ViewConfiguration ViewType = "configuration"

	// ViewJobs lists what is running and what has run this session. It is
	// typed like any other view rather than reached by an uppercase key: the
	// uppercase vocabulary is for actions *within* a view, and changing view
	// goes through `:` (Rule 111).
	ViewJobs ViewType = "jobs"

	// ViewTemplates is the catalog of repository templates: what a new
	// repository can be filled from, and where each one lives. A view for the
	// reason ViewJobs is — changing view goes through `:` (Rule 111).
	ViewTemplates ViewType = "templates"

	// ViewAbout says which build is running and where it keeps its files. It is
	// a view rather than an uppercase key for the reason ViewJobs is: the
	// uppercase vocabulary acts on a resource *within* a screen, and this one
	// is a screen. It is also why it is not an overlay like `?` — the help
	// answers "what can I press here", which is a different question and one
	// that every view answers for itself.
	ViewAbout ViewType = "about"

	// ViewFiles browses the whole filesystem (§3.95). It is also what the
	// router lends a form's Browse button, as a picker.
	ViewFiles ViewType = "files"

	// ViewViewer is opened by the router on another view's request — a file in
	// workspaces, an inspect or a log in containers — and never by name. It is
	// deliberately absent from viewNames: `:viewer` would open a pane saying
	// there is nothing in it, and app.default_view would offer it as a landing
	// view, which is the defect ViewNames() was split from FullNames() to fix.
	ViewViewer ViewType = "viewer"
)

// routerViews are the views the router opens itself. They are real views with
// real headers and help, so the contract tests have to reach them — see
// AllViewNames — but nothing a user can type resolves to one.
var routerViews = []ViewType{ViewViewer}

// CommandType represents the command type
type CommandType string

const (
	CommandView    CommandType = "view"
	CommandContext CommandType = "context"
	CommandQuit    CommandType = "quit"
	CommandUnknown CommandType = "unknown"
)

// Command represents a parsed command
type Command struct {
	Type CommandType
	View ViewType // For view commands
	Args []string // For context commands
}

// viewNames maps every accepted spelling to the view it names. The key equal to
// the ViewType is its full name; every other key is an alias.
//
// This map is the single source for both parsing and completion. They used to
// be separate lists and had drifted: four views could be typed in full but not
// tab-completed, and `netdiag` was documented everywhere while only `net`
// parsed (§1.3 D16, D17).
var viewNames = map[string]ViewType{
	"dashboard":     ViewDashboard,
	"dash":          ViewDashboard,
	"d":             ViewDashboard,
	"status":        ViewStatus,
	"s":             ViewStatus,
	"git-auth":      ViewGitAuth,
	"ga":            ViewGitAuth,
	"git-explorer":  ViewGitExplorer,
	"ge":            ViewGitExplorer,
	"workspaces":    ViewWorkspaces,
	"ws":            ViewWorkspaces,
	"w":             ViewWorkspaces,
	"security":      ViewSecurity,
	"sec":           ViewSecurity,
	"containers":    ViewContainers,
	"cont":          ViewContainers,
	"ct":            ViewContainers,
	"oci-resources": ViewOCIResources,
	"oci":           ViewOCIResources,
	"netdiag":       ViewNetdiag,
	"net":           ViewNetdiag,
	"configuration": ViewConfiguration,
	"config":        ViewConfiguration,
	"cfg":           ViewConfiguration,
	"jobs":          ViewJobs,
	"j":             ViewJobs,
	"templates":     ViewTemplates,
	"tpl":           ViewTemplates,
	"about":         ViewAbout,
	// No one-letter alias: `a` is worth more than this view, which is opened
	// once to read a version and not returned to.
	"version": ViewAbout,
	"files":   ViewFiles,
	"fs":      ViewFiles,
}

// resolveView looks a spelling up in viewNames, the single source for both
// parsing and completion.
func resolveView(name string) (ViewType, bool) {
	view, ok := viewNames[name]
	return view, ok
}

// actionNames are the commands that do not name a view. They take arguments
// (`context work`, `theme mocha`) or none at all (`quit`).
var actionNames = map[string]CommandType{
	"context": CommandContext,
	"quit":    CommandQuit,
}

// actionAliases maps a short form to the full command in actionNames. Kept
// apart from viewNames because completion displays the two differently.
var actionAliases = map[string]string{
	"ctx": "context",
	"c":   "context",
	"q":   "quit",
}

// normalize strips the leading colon and the case, so `:Status ` and `status`
// are the same command.
func normalize(input string) string {
	return strings.ToLower(strings.TrimPrefix(strings.TrimSpace(input), ":"))
}

// ParseCommand parses a command and returns a structured Command
func ParseCommand(input string) Command {
	parts := strings.Fields(normalize(input))
	if len(parts) == 0 {
		return Command{Type: CommandUnknown}
	}

	mainCmd, args := parts[0], parts[1:]
	if full, isAlias := actionAliases[mainCmd]; isAlias {
		mainCmd = full
	}

	if action, ok := actionNames[mainCmd]; ok {
		if action == CommandQuit {
			return Command{Type: CommandQuit}
		}
		return Command{Type: action, Args: args}
	}

	if view, ok := resolveView(mainCmd); ok {
		return Command{Type: CommandView, View: view}
	}

	return Command{Type: CommandUnknown}
}

// Parse resolves a view name alone, without action commands. This is the form
// used to read `default_view` in configuration.
// Returns an empty view, without error, when the name is not recognized.
func Parse(input string) (ViewType, error) {
	if view, ok := resolveView(normalize(input)); ok {
		return view, nil
	}
	return "", nil
}

// GetAliases returns every alias with the full name it abbreviates, views and
// action commands combined.
func GetAliases() map[string]string {
	aliases := make(map[string]string, len(viewNames)+len(actionAliases))
	for name, view := range viewNames {
		if name != string(view) {
			aliases[name] = string(view)
		}
	}
	maps.Copy(aliases, actionAliases)
	return aliases

	a.currentView = view

	newView, ok := a.views[view]
	if !ok {
		return nil
	}
	log.Printf("Switching to view: %s, calling Init()", view)

	// Init() + a WindowSizeMsg to force the resize, plus the snapshot of
	// work in progress: the view was kept up to date for as long as it
	// existed, but a view built just now was not there for anything that had
	// already started.
	return tea.Batch(newView.Init(), a.requestResize(), a.sendJobsTo(view))
}

// settleCurrentView gives the view being left the chance to write down what it
// holds, and lets it refuse to be left.
//
// A view that does not implement LeavingView is left without ceremony, which is
// every view but one: the configuration form is the only screen that keeps a
// value in a widget rather than in the model until a key moves the cursor.
//
// Returning false keeps the current view *and* whatever it wants to say about
// why — the caller passes that Cmd on rather than the switch it did not make.
func (a *App) settleCurrentView() (tea.Cmd, bool) {
	current, exists := a.views[a.currentView]
	if !exists {
		return nil, true
	}
	leaver, implements := current.(LeavingView)
	if !implements {
		return nil, true
	}
	settled, cmd, ok := leaver.Leave()
	a.views[a.currentView] = settled
	return cmd, ok
}

// createView creates a view (lazy loading)
func (a *App) createView(view command.ViewType) {
	if _, exists := a.views[view]; exists && view != command.ViewGitAuth {
		return
	}

	switch view {
	case command.ViewDashboard:
		a.views[view] = dashboard.New(a.config, a.sharedState)
	case command.ViewStatus:
		a.views[view] = status.New(a.config)
	case command.ViewGitAuth:
		a.views[view] = a.newAuthView()
	case command.ViewGitExplorer:
		a.views[view] = explorer.New(a.config, a.sharedState)
	case command.ViewWorkspaces:
		a.views[view] = workspaces.New(a.config, a.sharedState.Secrets.Storage)
	case command.ViewSecurity:
		a.views[view] = security.New(a.config, a.sharedState.Secrets.Storage)
	case command.ViewContainers:
		a.views[view] = containers.New(a.config)
	case command.ViewOCIResources:
		a.views[view] = ociresources.New(a.config)
	case command.ViewNetdiag:
		a.views[view] = netdiag.New(a.config)
	case command.ViewConfiguration:
		a.views[view] = configuration.New(a.config, a.mcpFacts())
	case command.ViewJobs:
		a.views[view] = jobsview.New(a.config, a.currentContext)
	case command.ViewTemplates:
		a.views[view] = templates.New(a.config, a.sharedState.Secrets.Storage)
	case command.ViewAbout:
		a.views[view] = about.New(a.config)
	case command.ViewFiles:
		a.views[view] = filebrowser.New(a.config)
	case command.ViewViewer:
		// Empty: the viewer is normally installed with its source by
		// handleViewerOpenRequest, and this case exists so the router can build
		// one like any other view — which is what the contract test does.
		a.views[view] = uiviewer.New(a.config)
	}
	// Built after the detection landed, it was not there to receive it.
	a.sendScanToolsTo(view)
}

// newAuthView builds the GitLab auth view against this context's credentials.
// It is rebuilt on every switch rather than cached, so the form reflects the
// session that is current now.
func (a *App) newAuthView() tea.Model {
	log.Printf("Creating GitLab auth view with context: %s", a.currentContext)

	authView := auth.New(a.config, a.sharedState.Secrets, a.sharedState.SecretNotices)
	if a.sharedState.IsAuthenticated {
		authView.SetAuth(a.sharedState.Forge, a.sharedState.CurrentUser)
	}
	return authView
}

// updateCompletions updates the suggestions based on the current input
func (a *App) updateCompletions() {
	input := a.commandInput.Value()

	// Reset index if input changes
	if input != a.completionInput {
		a.completionIndex = 0
		a.completionInput = input
	}

	a.completionSuggestions = a.completionEngine.GetSuggestions(input)
}

